-- migrate:up
-- Lab Member rules for record access (A1a Task 2; spec docs/superpowers/specs/2026-10-12-record-access-design.md
-- section 3). Migration 165 added the restricted flag and the five *_access tables; this one applies the rules
-- that read them. Per record type a record is visible to the people LISTED on it (owner, access list, the
-- project's PI) and, unless it is restricted, to the people who were involved through inheritance (as before).
-- Operations and tests also pass the gates of their sample, project and campaign; a restricted project or
-- campaign hides what is inside it. Update and delete are never wider than read. Changes against main:
--   * physical_samples, manufacturing_operations, test_sessions, campaigns, projects: read, update, delete
--     (campaigns now update for owner or a Can edit person, delete for the owner; operations and tests delete
--     the owner behind the same gates);
--   * every collection that follows a record through `via` (sample_data_files, sample_stock_provenance,
--     sample_genealogy, campaign_samples, operation_data_files, machining_force_analysis, fast_run_data,
--     session_data_files, the additional-operators junctions, test_sessions_subject, project_investigators);
--   * sample_co_owners: update and delete are owner-only (before, any co-owner could repoint or delete a
--     co-owner row, which on a restricted sample leaks it);
--   * project_rollup: access rows with role investigator count as investigators (the restricted column arrives
--     with migration 167, which refines this row);
--   * the five *_access tables get a Lab Member read row for the rows about themselves (person_id.user_id =
--     $CURRENT_USER) and nothing else: the filters read them inside a legal _some, where Directus applies the
--     table's own rule, and the record-access endpoint is the only writer.
-- The eleven *_params tables have no rows to rule: migration 20260623000032 dropped them (their fields are columns
-- of manufacturing_operations and test_sessions and follow those rows).
--
-- The rows below are `python3 scripts/gen_access_rules.py --values --only <the collections above>` (a snapshot of
-- the rules on 2026-10-12, as in 20261012000161). A Lab Member row whose permissions or validation differ is
-- updated; a missing row is inserted (fields '*'). What it changes or adds is kept in
-- d1_private.lab_member_access_rules_backup for `down`.
--
-- Apply this TOGETHER WITH the Task 3 extensions of the same release (d1-access-guard with the owner-only
-- restricted field and the manage-rule junction guards, and d1-record-access, the only writer of the access
-- tables) and with migration 167. Directus caches permissions: flush Redis and restart Directus after applying.

CREATE SCHEMA IF NOT EXISTS d1_private;

CREATE TABLE IF NOT EXISTS d1_private.lab_member_access_rules_backup (
    id          INTEGER PRIMARY KEY,
    permissions JSON,
    validation  JSON,
    inserted    BOOLEAN NOT NULL DEFAULT FALSE
);
COMMENT ON TABLE d1_private.lab_member_access_rules_backup IS
    'Migration 20261012000166: the Lab Member permission rows it changed (directus_permissions.id with the old permissions and validation) or inserted (inserted = true). `migrate:down` restores or deletes them and drops the table.';

CREATE TEMP TABLE _lm_access_rules (collection TEXT, action TEXT, filter JSON, validation JSON, fields TEXT) ON COMMIT DROP;

-- First keep the rows that are about to change, then change exactly those.
SELECT p.id, p.permissions, p.validation
  FROM directus_permissions p
  JOIN _lm_access_rules g ON g.collection = p.collection AND g.action = p.action
 WHERE p.policy = '20000002-0000-0000-0000-000000000002'
   AND (p.permissions::jsonb IS DISTINCT FROM g.filter::jsonb
        OR p.validation::jsonb IS DISTINCT FROM g.validation::jsonb)
ON CONFLICT (id) DO NOTHING;

UPDATE directus_permissions p
   SET permissions = g.filter, validation = g.validation
  FROM _lm_access_rules g, d1_private.lab_member_access_rules_backup b
 WHERE b.id = p.id AND NOT b.inserted
   AND g.collection = p.collection AND g.action = p.action;

WITH added AS (
    SELECT g.collection, g.action, g.filter, g.validation, g.fields, '20000002-0000-0000-0000-000000000002'
      FROM _lm_access_rules g
     WHERE NOT EXISTS (SELECT 1 FROM directus_permissions p
                        WHERE p.policy = '20000002-0000-0000-0000-000000000002'
                          AND p.collection = g.collection AND p.action = g.action)
    RETURNING id
)
SELECT id, TRUE FROM added;

-- migrate:down
DELETE FROM directus_permissions p
 USING d1_private.lab_member_access_rules_backup b
 WHERE b.id = p.id AND b.inserted;

UPDATE directus_permissions p
   SET permissions = b.permissions, validation = b.validation
  FROM d1_private.lab_member_access_rules_backup b
 WHERE b.id = p.id AND NOT b.inserted;

DROP TABLE IF EXISTS d1_private.lab_member_access_rules_backup;
